<?php
declare(strict_types=1);

require_once dirname(__DIR__) . '/config.php';
exigirLogin();

$id=(int)($_GET['id']??0);$usuarioId=(int)$_SESSION['usuario_id'];$stmt=$pdo->prepare('SELECT t.*,a.nome AS area_nome,u.nome AS criador_nome FROM treinamentos t JOIN areas a ON a.id=t.area_id LEFT JOIN usuarios u ON u.id=t.criado_por WHERE t.id=?');$stmt->execute([$id]);$treinamento=$stmt->fetch();if(!$treinamento||(!temPerfil('admin')&&$treinamento['status']!=='publicado')){http_response_code(404);exit('Treinamento não encontrado.');}
$sqlAulas='SELECT a.id,a.titulo,a.objetivo,a.ordem,a.duracao_min,a.status,MAX(CASE WHEN p.concluida=TRUE THEN 1 ELSE 0 END) AS concluida FROM aulas a LEFT JOIN progresso_aulas p ON p.aula_id=a.id AND p.usuario_id=? WHERE a.treinamento_id=?';if(!temPerfil('admin')){$sqlAulas.=" AND a.status='publicado'";}$sqlAulas.=' GROUP BY a.id,a.titulo,a.objetivo,a.ordem,a.duracao_min,a.status ORDER BY a.ordem,a.id';$stmt=$pdo->prepare($sqlAulas);$stmt->execute([$usuarioId,$id]);$aulas=$stmt->fetchAll();$total=0;$concluidas=0;foreach($aulas as $aula){if($aula['status']==='publicado'){$total++;$concluidas+=valorBooleano($aula['concluida'])?1:0;}}$percentual=$total?min(100,(int)round($concluidas/$total*100)):0;$stmt=$pdo->prepare('SELECT id,titulo,nota_minima FROM avaliacoes WHERE treinamento_id=? AND ativa=TRUE ORDER BY criado_em');$stmt->execute([$id]);$avaliacoes=$stmt->fetchAll();
?><!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo esc($treinamento['titulo']);?> - TrainHub</title><link rel="stylesheet" href="css/app.css?v=1.0"><style>.curso-cabecalho{padding:28px}.curso-cabecalho h1{margin:8px 0 12px;font-size:clamp(28px,4vw,43px)}.curso-cabecalho>p{color:var(--th-muted);font-size:17px;line-height:1.6}.curso-info{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}.aula-linha{display:grid;grid-template-columns:34px minmax(0,1fr) auto;gap:12px;align-items:center}.aula-numero{width:32px;height:32px;display:grid;place-items:center;border-radius:50%;background:var(--th-card-2);font-weight:700}.aula-linha.concluida .aula-numero{background:#1d704d}.avaliacoes-lista{margin-top:22px}</style></head><body><header class="th-topbar"><a class="th-logo" href="inicio.php"><img src="assets/logo.png" alt="TrainHub"></a><a class="th-avatar" href="perfil.php">●</a></header><main class="th-shell"><a class="th-back" href="<?php echo temPerfil('admin')?'treinamentos.php':'inicio.php';?>">←</a><article class="th-panel curso-cabecalho"><span class="th-badge"><?php echo esc($treinamento['area_nome']);?></span><h1><?php echo esc($treinamento['titulo']);?></h1><p><?php echo esc($treinamento['descricao']?:'Este treinamento ainda não possui descrição.');?></p><div class="curso-info"><span class="th-badge"><?php echo esc($treinamento['carga_horaria']);?> horas</span><span class="th-badge <?php echo $treinamento['status']==='publicado'?'th-badge-success':'th-badge-warning';?>"><?php echo esc($treinamento['status']);?></span><span class="th-badge">Criado por <?php echo esc($treinamento['criador_nome']?:'equipe');?></span></div><div class="th-card-row"><strong>Seu progresso: <?php echo $percentual;?>%</strong><span class="th-meta"><?php echo $concluidas;?> de <?php echo $total;?> aulas</span></div><div class="th-progress" style="margin-top:8px"><span style="width:<?php echo $percentual;?>%"></span></div></article><section class="th-panel" style="margin-top:22px"><div class="th-card-row"><h2>Aulas</h2><?php if(temPerfil('admin')):?><a class="th-button" href="aulas.php?treinamento_id=<?php echo $id;?>">+ Cadastrar aula</a><?php endif;?></div><div class="th-list" style="margin-top:14px"><?php if(!$aulas):?><p class="th-empty">Nenhuma aula disponível neste treinamento.</p><?php endif;?><?php foreach($aulas as $aula):$feita=valorBooleano($aula['concluida']);?><article class="th-card aula-linha <?php echo $feita?'concluida':'';?>"><span class="aula-numero"><?php echo $feita?'✓':(int)$aula['ordem'];?></span><div><strong><?php echo esc($aula['titulo']);?></strong><p class="th-meta"><?php echo esc($aula['objetivo']?:'Conteúdo disponível para estudo.');?> · <?php echo (int)$aula['duracao_min'];?> min</p></div><a class="th-button" href="aula-template.php?id=<?php echo (int)$aula['id'];?>"><?php echo $feita?'Revisar':'Estudar';?> →</a></article><?php endforeach;?></div></section><section class="th-panel avaliacoes-lista"><div class="th-card-row"><h2>Avaliações</h2><a class="th-button th-button-secondary" href="avaliacoes.php?treinamento_id=<?php echo $id;?>">Ver todas</a></div><?php if(!$avaliacoes):?><p class="th-meta">Nenhuma avaliação disponível.</p><?php else:?><div class="th-list" style="margin-top:12px"><?php foreach($avaliacoes as $avaliacao):?><div class="th-card th-card-row"><span><strong><?php echo esc($avaliacao['titulo']);?></strong><small class="th-meta">Nota mínima <?php echo esc($avaliacao['nota_minima']);?></small></span><a class="th-button" href="avaliacoes.php?id=<?php echo (int)$avaliacao['id'];?>">Responder</a></div><?php endforeach;?></div><?php endif;?></section></main></body></html>
